-- =============================================================================
--  conf/input.lua — keyboard, mouse and touchpad
-- =============================================================================
local S = require("lib.settings")

hl.config({
    input = {
        kb_layout    = S.str("KB_LAYOUT", "us"),
        kb_variant   = S.str("KB_VARIANT", ""),
        kb_model     = "",
        kb_options   = S.str("KB_OPTIONS", ""),
        kb_rules     = "",
        follow_mouse = 1,
        sensitivity  = S.num("MOUSE_SENSITIVITY", 0),   -- -1.0 .. 1.0
        touchpad     = {
            natural_scroll = S.bool("NATURAL_SCROLL", true),
        },
    },
})

// hyprland/workspaces — dots; the active one stretches into a pill (CSS)
{
    "hyprland/workspaces": {
        "format": "{icon}",
        "format-icons": { "default": "", "active": "", "urgent": "" },
        "on-click": "activate",
        "on-scroll-up": "hyprctl dispatch 'hl.dsp.focus({ workspace = \"e-1\" })'",
        "on-scroll-down": "hyprctl dispatch 'hl.dsp.focus({ workspace = \"e+1\" })'",
        "persistent-workspaces": { "*": 5 },
        "tooltip": false
    }
}

// clock — "jeu. 08 oct.  14:32" (system locale); click = calendar panel, right click = full date
{
    "clock": {
        "format": "{:L%a %d %b   %H:%M}",
        "format-alt": "{:L%A %d %B %Y   %H:%M:%S}",
        "interval": 1,
        "tooltip": false,
        "on-click": "$XDG_CONFIG_HOME/hypr/scripts/quickpanel.sh calendar",
        "actions": {
            "on-click-right": "mode"
        }
    }
}

/* =============================================================================
   style/base.css — rules shared by every bar style
   =============================================================================
   The look itself (capsules / floating / solid / minimal) is in
   style/presets/<BAR_STYLE>.css; sizes come from waybar/build.py (settings).
   Colors: colors.css (generated) = palette + @a1…@a6 accents.
   ============================================================================= */

* {
    border: none;
    min-height: 0;
    box-shadow: none;
}

window#waybar {
    background: transparent;
    color: @on_surface;
}
window#waybar.hidden { opacity: 0; }

/* Capsules = groups: #session (left items), #time (clock), #status, #system */
#session, #time, #status, #system { padding: 0 4px; }

/* Modules inside capsules: flat, tinted on hover */
#session > widget > *, #time > widget > *, #status > widget > *, #system > widget > *, .extra {
    color: @on_surface;
    background: transparent;
    padding: 0 8px;
    margin: 3px 0;
    border-radius: 7px;
    transition: background-color 200ms ease-out, color 200ms ease-out;
}
#session > widget > *:hover, #time > widget > *:hover, #status > widget > *:hover, #system > widget > *:hover {
    background-color: alpha(@a1, 0.16);
}

tooltip {
    background: alpha(@surface_container, 0.96);
    border: 1px solid alpha(@a1, 0.30);
    border-radius: 10px;
    padding: 4px;
}
tooltip label { color: @on_surface; }

